/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
# connected change region per frame vs prev; get center and size
for i in range(0,96,3):
    if i==0: diff=np.ones(d[0].shape[:2],bool)
    else: diff=(np.abs(d[i]-d[max(0,i-1)]).sum(2)>30)
    ys,xs=np.where(diff)
    if len(xs): print(i,'cx%6.1f cy%5.1f w%3d h%3d n%5d'%(xs.mean(),ys.mean(),xs.max()-xs.min(),ys.max()-ys.min(),len(xs)))
\""
